-- ============================================================================
-- V049: Sprint 8.6 AI Micro-Lessons Triggered by Diagnosed Patterns
-- Invariants: INV-MICRO-001..006, ADR-004 SHA-256 verification, ADR-006 training_eligible=FALSE
-- ============================================================================

CREATE TABLE IF NOT EXISTS micro_lesson_catalog (
    card_id                    UUID PRIMARY KEY,
    mistake_code               VARCHAR(64) NOT NULL,
    locale                     VARCHAR(10) NOT NULL,
    schema_version             VARCHAR(16) NOT NULL DEFAULT '1.0.0',
    title                      VARCHAR(160) NOT NULL,
    focus_badge_label          VARCHAR(80) NOT NULL,
    estimated_duration_seconds INTEGER NOT NULL,
    card_payload               JSONB NOT NULL,
    verification_status        VARCHAR(20) NOT NULL DEFAULT 'VERIFIED',
    verification_hash          VARCHAR(64) NOT NULL,
    verifier_version           VARCHAR(32) NOT NULL DEFAULT 'sympy-1.12-v1',
    created_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_micro_lesson_catalog_mistake_locale UNIQUE (mistake_code, locale),
    CONSTRAINT chk_micro_lesson_catalog_locale CHECK (locale IN ('tr-TR', 'en-US')),
    CONSTRAINT chk_micro_lesson_catalog_duration CHECK (estimated_duration_seconds BETWEEN 60 AND 180),
    CONSTRAINT chk_micro_lesson_catalog_verification_status CHECK (verification_status IN ('VERIFIED', 'REJECTED')),
    CONSTRAINT chk_micro_lesson_catalog_hash_hex CHECK (verification_hash ~ '^[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS idx_micro_lesson_catalog_lookup
    ON micro_lesson_catalog (mistake_code, locale)
    WHERE verification_status = 'VERIFIED';

CREATE TABLE IF NOT EXISTS learner_micro_lesson_completions (
    completion_id      UUID PRIMARY KEY,
    user_id            UUID NOT NULL,
    card_id            UUID NOT NULL REFERENCES micro_lesson_catalog(card_id) ON DELETE RESTRICT,
    mistake_code       VARCHAR(64) NOT NULL,
    locale             VARCHAR(10) NOT NULL,
    source_attempt_id  UUID NULL,
    trigger_source     VARCHAR(32) NOT NULL,
    selected_option_id VARCHAR(32) NOT NULL,
    quick_check_passed BOOLEAN NOT NULL,
    dwell_time_ms      INTEGER NOT NULL,
    idempotency_key    VARCHAR(128) NOT NULL,
    training_eligible  BOOLEAN NOT NULL DEFAULT FALSE,
    completed_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_learner_micro_lesson_idempotency UNIQUE (user_id, idempotency_key),
    CONSTRAINT chk_learner_micro_lesson_locale CHECK (locale IN ('tr-TR', 'en-US')),
    CONSTRAINT chk_learner_micro_lesson_trigger CHECK (trigger_source IN ('TWIN_SECOND_FAILURE', 'SOCRATIC_RUNG_2', 'COACH_REPAIR_DRAWER')),
    CONSTRAINT chk_learner_micro_lesson_dwell CHECK (dwell_time_ms BETWEEN 1000 AND 600000),
    CONSTRAINT chk_learner_micro_lesson_training_false CHECK (training_eligible = FALSE)
);

CREATE INDEX IF NOT EXISTS idx_learner_micro_lesson_user_mistake
    ON learner_micro_lesson_completions (user_id, mistake_code, completed_at DESC);

CREATE INDEX IF NOT EXISTS idx_learner_micro_lesson_user_purge
    ON learner_micro_lesson_completions (user_id);

-- Seed 34 SymPy-verified canonical micro-lesson cards (17 mistake codes x 2 locales)
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000001', 'ALG_SIGN_FLIP_DISTRIBUTE', 'tr-TR', '1.0.0', 'Parantez Önündeki Eksi İşaretini Dağıtma', 'Odak Noktası · İşaret Dağılımı', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"-2x - 6","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies -2(1 - 3) = 4 \\neq -2(1) - 6 = -8","promptLatex":"-2(x - 3)","sympyEquivalenceCheckExpr":"simplify(-2*(x - 3) - (-2*x + 6)) == 0","sympyTargetExpr":"-2*(x - 3)","sympyTrapExpr":"-2*x - 6","sympyValidExpr":"-2*x + 6","verifiedStepLatex":"-2x + 6","whyTrapFailsExplanation":"Parantezin yalnızca ilk terimi -2 ile çarpılıp -3 terimi eski işaretiyle bırakıldığında ifade -2x - 6 olur; oysa (-2)·(-3) = +6 olmalıdır."},"coreRule":{"canonicalLatexFormula":"-a(b - c) = -ab + ac","conciseExplanation":"Parantez dışındaki negatif katsayı, içerideki birinci terimle birlikte ikinci ve sonraki tüm terimlerin de işaretini tersine çevirir.","estimatedSeconds":30,"ruleTitle":"Eksi Çarpan Her Terime Dağılır","sympyCheckExpr":"-a*(b - c) == -a*b + a*c"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"-6x - 15","optionId":"A","rationale":"İkinci terimdeki eksi ile dıştaki eksi çarpıldığında artı (+15) elde edilir."},{"isCorrect":true,"latexOrText":"-6x + 15","optionId":"B","rationale":"Harika! (-3)·(2x) = -6x ve (-3)·(-5) = +15 olarak her iki terim doğru dağıtıldı."},{"isCorrect":false,"latexOrText":"6x - 15","optionId":"C","rationale":"İlk terimdeki negatif katsayı işaretini korur: (-3)·(2x) = -6x."}],"questionLatex":"-3(2x - 5)","questionPrompt":"-3(2x - 5) ifadesinin eşdeğer açılımı hangisidir?"}}'::jsonb, 'VERIFIED', '231efa2277b1cfb64c04e417d52bf31ef2e2c5b1dc99ad24c1f835b8da96b2c0', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000002', 'ALG_SIGN_FLIP_DISTRIBUTE', 'en-US', '1.0.0', 'Distributing a Negative Factor Across Parentheses', 'Focus Area · Sign Distribution', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"-2x - 6","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies -2(1 - 3) = 4 \\neq -2(1) - 6 = -8","promptLatex":"-2(x - 3)","sympyEquivalenceCheckExpr":"simplify(-2*(x - 3) - (-2*x + 6)) == 0","sympyTargetExpr":"-2*(x - 3)","sympyTrapExpr":"-2*x - 6","sympyValidExpr":"-2*x + 6","verifiedStepLatex":"-2x + 6","whyTrapFailsExplanation":"Multiplying only x by -2 leaves -3 unchanged and yields -2x - 6, whereas (-2)(-3) = +6."},"coreRule":{"canonicalLatexFormula":"-a(b - c) = -ab + ac","conciseExplanation":"A negative multiplier outside parentheses flips the sign of every term inside, not just the first term.","estimatedSeconds":30,"ruleTitle":"Multiply Every Inner Term by the Negative Factor","sympyCheckExpr":"-a*(b - c) == -a*b + a*c"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"-6x - 15","optionId":"A","rationale":"Check the second term: multiplying two negatives gives +15."},{"isCorrect":true,"latexOrText":"-6x + 15","optionId":"B","rationale":"Spot on! Both (-3)(2x) = -6x and (-3)(-5) = +15 are distributed accurately."},{"isCorrect":false,"latexOrText":"6x - 15","optionId":"C","rationale":"The leading term keeps its negative product: (-3)(2x) = -6x."}],"questionLatex":"-3(2x - 5)","questionPrompt":"Which expanded expression is equivalent to -3(2x - 5)?"}}'::jsonb, 'VERIFIED', '78f88d3c31c8d9266e54fbaf64b199fa261df78a3df49100f3faf62eae793d7c', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000003', 'ALG_FRESHMAN_DREAM_POWER', 'tr-TR', '1.0.0', 'Toplamın Karesinde Ortadaki Çarpım Terimi', 'Odak Noktası · Tam Kare Özdeşliği', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x^2 + 9","counterexampleBindings":{"x":2},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 2 \\implies (2 + 3)^2 = 25 \\neq 2^2 + 9 = 13","promptLatex":"(x + 3)^2","sympyEquivalenceCheckExpr":"simplify((x + 3)**2 - (x**2 + 6*x + 9)) == 0","sympyTargetExpr":"(x + 3)**2","sympyTrapExpr":"x**2 + 9","sympyValidExpr":"x**2 + 6*x + 9","verifiedStepLatex":"x^2 + 6x + 9","whyTrapFailsExplanation":"Üssü terimlere ayrı ayrı dağıtmak ortadaki 2·x·3 = 6x çapraz terimini atlar ve x = 2 değerinde 25 yerine 13 üretir."},"coreRule":{"canonicalLatexFormula":"(a + b)^2 = a^2 + 2ab + b^2","conciseExplanation":"(a + b)^2 ifadesi (a + b)(a + b) çarpımıdır; her zaman baştaki ve sondaki karelerin yanında 2ab ortanca terimi de oluşur.","estimatedSeconds":30,"ruleTitle":"Üs Toplama İşlemine Doğrudan Dağılmaz","sympyCheckExpr":"(a + b)**2 == a**2 + 2*a*b + b**2"},"interactiveQuickCheck":{"correctOptionId":"C","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x^2 - 16","optionId":"A","rationale":"İki kare farkı (x-4)(x+4) için geçerlidir; tam karede ortanca terim bulunur."},{"isCorrect":false,"latexOrText":"x^2 + 16","optionId":"B","rationale":"Ortadaki -2·4·x = -8x çapraz terimi unutulmamalıdır."},{"isCorrect":true,"latexOrText":"x^2 - 8x + 16","optionId":"C","rationale":"Doğru! Birincinin karesi, iki çarpımın iki katı (-8x) ve ikincinin karesi (+16) eksiksiz yazıldı."}],"questionLatex":"(x - 4)^2","questionPrompt":"(x - 4)^2 ifadesinin doğru açılımı hangisidir?"}}'::jsonb, 'VERIFIED', 'cb75cc22e242b3b1c7e0cab2354386f418f786999443f6541d11c47f4a4dbfc4', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000004', 'ALG_FRESHMAN_DREAM_POWER', 'en-US', '1.0.0', 'Keeping the Cross Term in Binomial Squares', 'Focus Area · Binomial Expansion', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x^2 + 9","counterexampleBindings":{"x":2},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 2 \\implies (2 + 3)^2 = 25 \\neq 2^2 + 9 = 13","promptLatex":"(x + 3)^2","sympyEquivalenceCheckExpr":"simplify((x + 3)**2 - (x**2 + 6*x + 9)) == 0","sympyTargetExpr":"(x + 3)**2","sympyTrapExpr":"x**2 + 9","sympyValidExpr":"x**2 + 6*x + 9","verifiedStepLatex":"x^2 + 6x + 9","whyTrapFailsExplanation":"Squaring each term separately drops the 6x cross term, giving 13 instead of 25 when x = 2."},"coreRule":{"canonicalLatexFormula":"(a + b)^2 = a^2 + 2ab + b^2","conciseExplanation":"(a + b)^2 means (a + b)(a + b), which always produces the cross term 2ab in addition to a^2 + b^2.","estimatedSeconds":30,"ruleTitle":"Exponents Do Not Distribute Over Addition","sympyCheckExpr":"(a + b)**2 == a**2 + 2*a*b + b**2"},"interactiveQuickCheck":{"correctOptionId":"C","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x^2 - 16","optionId":"A","rationale":"That matches (x - 4)(x + 4), not (x - 4)(x - 4)."},{"isCorrect":false,"latexOrText":"x^2 + 16","optionId":"B","rationale":"Remember to include the middle cross term -2(4x) = -8x."},{"isCorrect":true,"latexOrText":"x^2 - 8x + 16","optionId":"C","rationale":"Spot on! You kept the cross term -8x along with x^2 and +16."}],"questionLatex":"(x - 4)^2","questionPrompt":"Which expression equals (x - 4)^2?"}}'::jsonb, 'VERIFIED', '9cd9a5180777422c605eb36ad3ea976b987614c6945b974497173bae30e858cb', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000005', 'ALG_FRACTION_ADD_DENOM', 'tr-TR', '1.0.0', 'Rasyonel İfadelerde Ortak Payda Kuralı', 'Odak Noktası · Kesir Toplama', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"\\frac{2}{x + y}","counterexampleBindings":{"x":2,"y":3},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 2, y = 3 \\implies \\frac{1}{2} + \\frac{1}{3} = \\frac{5}{6} \\neq \\frac{2}{5}","promptLatex":"\\frac{1}{x} + \\frac{1}{y}","sympyEquivalenceCheckExpr":"simplify((1/x + 1/y) - (x + y)/(x*y)) == 0","sympyTargetExpr":"1/x + 1/y","sympyTrapExpr":"2/(x + y)","sympyValidExpr":"(x + y)/(x*y)","verifiedStepLatex":"\\frac{x + y}{xy}","whyTrapFailsExplanation":"Payları ve paydaları ayrı ayrı toplamak 2/(x + y) verir; x = 2, y = 3 için 5/6 yerine 2/5 sonucunu üretir."},"coreRule":{"canonicalLatexFormula":"\\frac{1}{x} + \\frac{1}{y} = \\frac{x + y}{xy}","conciseExplanation":"Farklı paydalı kesirleri toplarken önce ortak payda (xy) oluşturulur, ardından genişletilmiş paylar toplanır.","estimatedSeconds":30,"ruleTitle":"Paydalar Doğrudan Toplanmaz, Payda Eşitlenir","sympyCheckExpr":"1/x + 1/y == (x + y)/(x*y)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\frac{3}{a + b}","optionId":"A","rationale":"Farklı paydalar doğrudan toplanmaz; önce ortak payda ab kurulmalıdır."},{"isCorrect":true,"latexOrText":"\\frac{b + 2a}{ab}","optionId":"B","rationale":"Harika! İlk kesir b ile, ikinci kesir a ile genişletilip paylar toplandı."},{"isCorrect":false,"latexOrText":"\\frac{a + 2b}{ab}","optionId":"C","rationale":"İlk kesrin payı 1·b, ikinci kesrin payı 2·a olur; katsayı yerlerine dikkat edelim."}],"questionLatex":"\\frac{1}{a} + \\frac{2}{b}","questionPrompt":"1/a + 2/b toplamı (a, b ≠ 0) hangisine eşittir?"}}'::jsonb, 'VERIFIED', '996edc35871e6d7e8ec35523a63a012b7fc182c3d00e40664b7767cf777eda9b', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000006', 'ALG_FRACTION_ADD_DENOM', 'en-US', '1.0.0', 'Common Denominators Before Adding Fractions', 'Focus Area · Rational Addition', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"\\frac{2}{x + y}","counterexampleBindings":{"x":2,"y":3},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 2, y = 3 \\implies \\frac{1}{2} + \\frac{1}{3} = \\frac{5}{6} \\neq \\frac{2}{5}","promptLatex":"\\frac{1}{x} + \\frac{1}{y}","sympyEquivalenceCheckExpr":"simplify((1/x + 1/y) - (x + y)/(x*y)) == 0","sympyTargetExpr":"1/x + 1/y","sympyTrapExpr":"2/(x + y)","sympyValidExpr":"(x + y)/(x*y)","verifiedStepLatex":"\\frac{x + y}{xy}","whyTrapFailsExplanation":"Adding numerators and denominators across gives 2/(x + y), which evaluates to 2/5 instead of 5/6 at x = 2, y = 3."},"coreRule":{"canonicalLatexFormula":"\\frac{1}{x} + \\frac{1}{y} = \\frac{x + y}{xy}","conciseExplanation":"Convert fractions to a shared denominator (xy) before summing the scaled numerators.","estimatedSeconds":30,"ruleTitle":"Never Add Denominators Directly","sympyCheckExpr":"1/x + 1/y == (x + y)/(x*y)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\frac{3}{a + b}","optionId":"A","rationale":"Find a common denominator ab rather than adding a and b."},{"isCorrect":true,"latexOrText":"\\frac{b + 2a}{ab}","optionId":"B","rationale":"Spot on! Scaling by b/b and a/a yields (b + 2a)/(ab)."},{"isCorrect":false,"latexOrText":"\\frac{a + 2b}{ab}","optionId":"C","rationale":"Check which numerator gets multiplied by b versus a."}],"questionLatex":"\\frac{1}{a} + \\frac{2}{b}","questionPrompt":"Which fraction equals 1/a + 2/b for nonzero a and b?"}}'::jsonb, 'VERIFIED', '8dbbd9a0b97321c4d6a78a097040e5ad2836539c44c51bb36d6159a2a7b877e2', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000007', 'ALG_ROOT_LOST_BY_DIVISION', 'tr-TR', '1.0.0', 'Değişkenle Sadeleştirirken Kök Kaybetmeme', 'Odak Noktası · Çarpanlara Ayırma', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x - 5 = 0 \\implies \\{5\\}","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies 0^2 - 5(0) = 0 \\text{ (valid root)}","promptLatex":"x^2 - 5x = 0","sympyEquivalenceCheckExpr":"simplify((x**2 - 5*x) - x*(x - 5)) == 0","sympyTargetExpr":"x**2 - 5*x","sympyTrapExpr":"x - 5","sympyValidExpr":"x*(x - 5)","verifiedStepLatex":"x(x - 5) = 0 \\implies \\{0, 5\\}","whyTrapFailsExplanation":"Her iki tarafı x ile bölmek yalnızca x = 5 kökünü bırakır; oysa x = 0 değeri de x(x - 5) = 0 denklemini sağlar."},"coreRule":{"canonicalLatexFormula":"x^2 - kx = 0 \\iff x(x - k) = 0 \\iff x \\in \\{0, k\\}","conciseExplanation":"Denklemin iki tarafını x gibi sıfır olabilen bir ifadeye bölmek x = 0 kökünü siler; bunun yerine tüm terimleri bir tarafa alıp çarpanlara ayır.","estimatedSeconds":35,"ruleTitle":"Bilinmeyen İfadeye Bölmek Yerine Ortak Çarpan Parantezine Al","sympyCheckExpr":"x**2 - k*x == x*(x - k)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{7\\}","optionId":"A","rationale":"İki tarafı x''e bölmek x = 0 kökünü gözden kaçırır."},{"isCorrect":true,"latexOrText":"\\{0, 7\\}","optionId":"B","rationale":"Harika! x(x - 7) = 0 şeklinde çarpanlara ayırarak her iki kökü de korudun."},{"isCorrect":false,"latexOrText":"\\{-7, 7\\}","optionId":"C","rationale":"7x terimi karşıya -7x olarak geçer ve x parantezine alınır."}],"questionLatex":"x^2 = 7x","questionPrompt":"x^2 = 7x denkleminin gerçek sayılardaki çözüm kümesi nedir?"}}'::jsonb, 'VERIFIED', '1a079dbd5ffe0563c105f6ae00821234aab201304bcd10e34c5d7fba7bd749f4', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000008', 'ALG_ROOT_LOST_BY_DIVISION', 'en-US', '1.0.0', 'Preserving All Roots Instead of Dividing by a Variable', 'Focus Area · Factoring', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x - 5 = 0 \\implies \\{5\\}","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies 0^2 - 5(0) = 0 \\text{ (valid root)}","promptLatex":"x^2 - 5x = 0","sympyEquivalenceCheckExpr":"simplify((x**2 - 5*x) - x*(x - 5)) == 0","sympyTargetExpr":"x**2 - 5*x","sympyTrapExpr":"x - 5","sympyValidExpr":"x*(x - 5)","verifiedStepLatex":"x(x - 5) = 0 \\implies \\{0, 5\\}","whyTrapFailsExplanation":"Dividing by x leaves only x = 5, hiding the fact that x = 0 also makes x(x - 5) equal zero."},"coreRule":{"canonicalLatexFormula":"x^2 - kx = 0 \\iff x(x - k) = 0 \\iff x \\in \\{0, k\\}","conciseExplanation":"Dividing both sides of an equation by x discards the valid root x = 0; move all terms to one side and factor instead.","estimatedSeconds":35,"ruleTitle":"Factor Common Variables Rather Than Dividing Them Out","sympyCheckExpr":"x**2 - k*x == x*(x - k)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{7\\}","optionId":"A","rationale":"Dividing by x drops the solution x = 0."},{"isCorrect":true,"latexOrText":"\\{0, 7\\}","optionId":"B","rationale":"Spot on! Factoring x(x - 7) = 0 preserves both roots."},{"isCorrect":false,"latexOrText":"\\{-7, 7\\}","optionId":"C","rationale":"Subtract 7x to get x(x - 7) = 0 rather than x^2 = 49."}],"questionLatex":"x^2 = 7x","questionPrompt":"What is the complete real solution set of x^2 = 7x?"}}'::jsonb, 'VERIFIED', '58f27a6c99256630ce9096c0257f257d21bfae4948797f4618e68f07ecfdff85', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000009', 'DOM_EXTRANEOUS_ROOT_DENOM', 'tr-TR', '1.0.0', 'Paydayı Sıfır Yapan Yabancı Kökü Eleme', 'Odak Noktası · Tanım Kümesi', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x = 2 \\text{ kept as root}","counterexampleBindings":{"x":5},"estimatedSeconds":35,"numericCounterexampleLatex":"x = 2 \\implies x - 2 = 0 \\text{ (undefined)}; \\; x = 5 \\implies \\frac{21}{3} = 7","promptLatex":"\\frac{x^2 - 4}{x - 2} = 0","sympyEquivalenceCheckExpr":"simplify((x**2 - 4)/(x - 2) - (x + 2)) == 0","sympyTargetExpr":"(x**2 - 4)/(x - 2)","sympyTrapExpr":"x - 2","sympyValidExpr":"x + 2","verifiedStepLatex":"x + 2 = 0 \\text{ with } x \\neq 2 \\implies x = -2","whyTrapFailsExplanation":"Payı sıfırlayan x = 2 değeri paydayı da (2 - 2 = 0) sıfır yaptığı için tanımsızdır; gerçek tek çözüm x = -2 olur."},"coreRule":{"canonicalLatexFormula":"\\frac{x^2 - a^2}{x - a} = x + a \\quad (x \\neq a)","conciseExplanation":"Sadeleştirme veya içler dışlar çarpımı sonrası bulunan her aday kök, ilk denklemdeki tüm paydaları sıfırdan farklı tutmalıdır.","estimatedSeconds":30,"ruleTitle":"Rasyonel Denklemlerde Payda Sıfır Olamaz","sympyCheckExpr":"(x**2 - a**2)/(x - a) == x + a"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{-3, 3\\}","optionId":"A","rationale":"x = 3 değeri ilk kesrin paydasını sıfır yaptığı için elenmelidir."},{"isCorrect":true,"latexOrText":"\\{-3\\}","optionId":"B","rationale":"Harika! Paydayı sıfırlayan x = 3 elendi ve yalnızca x = -3 tutuldu."},{"isCorrect":false,"latexOrText":"\\{3\\}","optionId":"C","rationale":"x = 3 paydayı sıfırlar; oysa x = -3 payı sıfırlarken paydayı -6 yapar."}],"questionLatex":"\\frac{x^2 - 9}{x - 3} = 0","questionPrompt":"(x^2 - 9)/(x - 3) = 0 denkleminin çözüm kümesi nedir?"}}'::jsonb, 'VERIFIED', '7a38b283c38f46dd9f0ab35dabd85a01b1bafad953073e8e383a221df6a74767', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000010', 'DOM_EXTRANEOUS_ROOT_DENOM', 'en-US', '1.0.0', 'Filtering Extraneous Roots That Zero a Denominator', 'Focus Area · Domain Restriction', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x = 2 \\text{ kept as root}","counterexampleBindings":{"x":5},"estimatedSeconds":35,"numericCounterexampleLatex":"x = 2 \\implies x - 2 = 0 \\text{ (undefined)}; \\; x = 5 \\implies \\frac{21}{3} = 7","promptLatex":"\\frac{x^2 - 4}{x - 2} = 0","sympyEquivalenceCheckExpr":"simplify((x**2 - 4)/(x - 2) - (x + 2)) == 0","sympyTargetExpr":"(x**2 - 4)/(x - 2)","sympyTrapExpr":"x - 2","sympyValidExpr":"x + 2","verifiedStepLatex":"x + 2 = 0 \\text{ with } x \\neq 2 \\implies x = -2","whyTrapFailsExplanation":"Accepting x = 2 creates 0/0 in the original fraction; only x = -2 keeps the denominator nonzero."},"coreRule":{"canonicalLatexFormula":"\\frac{x^2 - a^2}{x - a} = x + a \\quad (x \\neq a)","conciseExplanation":"After canceling common factors or clearing fractions, discard any candidate value that makes an original denominator equal to zero.","estimatedSeconds":30,"ruleTitle":"Verify Candidate Roots Against Original Denominators","sympyCheckExpr":"(x**2 - a**2)/(x - a) == x + a"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{-3, 3\\}","optionId":"A","rationale":"Substituting x = 3 makes the denominator x - 3 equal to zero."},{"isCorrect":true,"latexOrText":"\\{-3\\}","optionId":"B","rationale":"Spot on! Excluding x = 3 leaves x = -3 as the valid solution."},{"isCorrect":false,"latexOrText":"\\{3\\}","optionId":"C","rationale":"x = 3 is excluded by the denominator, whereas x = -3 gives 0/(-6) = 0."}],"questionLatex":"\\frac{x^2 - 9}{x - 3} = 0","questionPrompt":"What is the solution set of (x^2 - 9)/(x - 3) = 0?"}}'::jsonb, 'VERIFIED', 'c02af1e0d01b0c11582794c91236a54ea04ce98fdac5a0a3d710cd03db9007c3', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000011', 'DOM_EVEN_ROOT_NEGATIVE', 'tr-TR', '1.0.0', 'Çift Dereceli Köklerde Mutlak Değer ve Tanım Şartı', 'Odak Noktası · Köklü İfadeler', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x","counterexampleBindings":{"x":-5},"estimatedSeconds":30,"numericCounterexampleLatex":"x = -5 \\implies \\sqrt{(-5)^2} = 5 \\neq -5","promptLatex":"\\sqrt{x^2}","sympyEquivalenceCheckExpr":"simplify(sqrt(x**2) - Abs(x)) == 0","sympyTargetExpr":"sqrt(x**2)","sympyTrapExpr":"x","sympyValidExpr":"Abs(x)","verifiedStepLatex":"|x|","whyTrapFailsExplanation":"x = -5 iken doğrudan x yazmak -5 sonucunu verir; ancak √((-5)²) = √25 = +5 = |-5| olmalıdır."},"coreRule":{"canonicalLatexFormula":"\\sqrt{x^2} = |x| = \\begin{cases} x, & x \\ge 0 \\\\ -x, & x < 0 \\end{cases}","conciseExplanation":"Gerçek sayılarda çift dereceli kök daima negatif olmayan bir sonuç verir; bu yüzden √(x²) doğrudan x değil |x| olarak dışarı çıkar.","estimatedSeconds":30,"ruleTitle":"Karekökün İçi Negatif Olamaz ve √(x²) = |x| Olur","sympyCheckExpr":"sqrt(x**2) == Abs(x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"2x","optionId":"A","rationale":"x negatif olduğunda √(x²) değeri x değil -x olarak açılır."},{"isCorrect":true,"latexOrText":"0","optionId":"B","rationale":"Harika! x < 0 için √(x²) = |x| = -x olduğundan (-x) + x = 0 bulunur."},{"isCorrect":false,"latexOrText":"-2x","optionId":"C","rationale":"|x| = -x ile +x toplanınca işaretler birbirini sıfırlar."}],"questionLatex":"\\sqrt{x^2} + x \\quad (x < 0)","questionPrompt":"x < 0 olmak üzere √(x²) + x ifadesinin değeri kaçtır?"}}'::jsonb, 'VERIFIED', '4164f16d4d47c5309afe505e6d274611000bec5e593a076e2de9b48cc0710ca5', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000012', 'DOM_EVEN_ROOT_NEGATIVE', 'en-US', '1.0.0', 'Principal Even Roots and Absolute Value Output', 'Focus Area · Radical Domains', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x","counterexampleBindings":{"x":-5},"estimatedSeconds":30,"numericCounterexampleLatex":"x = -5 \\implies \\sqrt{(-5)^2} = 5 \\neq -5","promptLatex":"\\sqrt{x^2}","sympyEquivalenceCheckExpr":"simplify(sqrt(x**2) - Abs(x)) == 0","sympyTargetExpr":"sqrt(x**2)","sympyTrapExpr":"x","sympyValidExpr":"Abs(x)","verifiedStepLatex":"|x|","whyTrapFailsExplanation":"Simplifying √(x²) to x yields -5 when x = -5, whereas √((-5)²) = √25 = 5 = |-5|."},"coreRule":{"canonicalLatexFormula":"\\sqrt{x^2} = |x| = \\begin{cases} x, & x \\ge 0 \\\\ -x, & x < 0 \\end{cases}","conciseExplanation":"Over the reals, an even root returns the principal non-negative value, so √(x²) simplifies to |x| rather than bare x.","estimatedSeconds":30,"ruleTitle":"Principal Square Roots Are Never Negative: √(x²) = |x|","sympyCheckExpr":"sqrt(x**2) == Abs(x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"2x","optionId":"A","rationale":"When x is negative, √(x²) equals -x rather than x."},{"isCorrect":true,"latexOrText":"0","optionId":"B","rationale":"Spot on! Since x < 0, √(x²) = |x| = -x, so (-x) + x = 0."},{"isCorrect":false,"latexOrText":"-2x","optionId":"C","rationale":"Adding -x and +x cancels out to 0."}],"questionLatex":"\\sqrt{x^2} + x \\quad (x < 0)","questionPrompt":"For x < 0, what does √(x²) + x simplify to?"}}'::jsonb, 'VERIFIED', '7bf1f7b939d60ab51de37c0ab9600d73269ebecef3126a237689fa6a92658521', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000013', 'DOM_LOG_NON_POSITIVE', 'tr-TR', '1.0.0', 'Logaritma İçinin Pozitif Kalma Zorunluluğu', 'Odak Noktası · Logaritma Tanım Kümesi', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"2\\ln(x)","counterexampleBindings":{"x":-3},"estimatedSeconds":35,"numericCounterexampleLatex":"x = -3 \\implies \\ln((-3)^2) = 2\\ln(3) \\in \\mathbb{R}, \\; 2\\ln(-3) \\notin \\mathbb{R}","promptLatex":"\\ln(x^2) \\quad (x \\neq 0)","sympyEquivalenceCheckExpr":"simplify(log(x**2) - 2*log(Abs(x))) == 0","sympyTargetExpr":"log(x**2)","sympyTrapExpr":"2*log(x)","sympyValidExpr":"2*log(Abs(x))","verifiedStepLatex":"2\\ln|x|","whyTrapFailsExplanation":"x = -3 değerinde (-3)² = 9 > 0 olduğundan ln(x²) tanımlıdır; fakat 2·ln(-3) gerçek sayılarda tanımsız kalır."},"coreRule":{"canonicalLatexFormula":"\\ln(x^2) = 2\\ln|x| \\quad (x \\neq 0)","conciseExplanation":"Logaritmanın içi daima > 0 olmalıdır. ln(x²) ifadesinde x negatif de olabileceği için 2·ln(x) değil 2·ln|x| yazılır.","estimatedSeconds":30,"ruleTitle":"Çift Kuvvet Logaritma Dışına İnerken Mutlak Değer Korunur","sympyCheckExpr":"log(x**2) == 2*log(Abs(x))"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x \\ge 4","optionId":"A","rationale":"Logaritmanın içi sıfır da olamaz; kesinlikle x - 4 > 0 şartı gerekir."},{"isCorrect":true,"latexOrText":"x > 4","optionId":"B","rationale":"Harika! Logaritma içi sıfırdan kesin büyük olmalıdır: x - 4 > 0 ⇒ x > 4."},{"isCorrect":false,"latexOrText":"x \\neq 4","optionId":"C","rationale":"Negatif değerler de (x < 4) gerçek logaritma için dışarıda kalır."}],"questionLatex":"\\ln(x - 4)","questionPrompt":"ln(x - 4) fonksiyonunun gerçek sayılardaki en geniş tanım kümesi nedir?"}}'::jsonb, 'VERIFIED', '64239ff90ca0b0838b3367f901389ff091e7e439927d2f47a1afde9a69c6f371', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000014', 'DOM_LOG_NON_POSITIVE', 'en-US', '1.0.0', 'Keeping Logarithm Arguments Strictly Positive', 'Focus Area · Logarithm Domains', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"2\\ln(x)","counterexampleBindings":{"x":-3},"estimatedSeconds":35,"numericCounterexampleLatex":"x = -3 \\implies \\ln((-3)^2) = 2\\ln(3) \\in \\mathbb{R}, \\; 2\\ln(-3) \\notin \\mathbb{R}","promptLatex":"\\ln(x^2) \\quad (x \\neq 0)","sympyEquivalenceCheckExpr":"simplify(log(x**2) - 2*log(Abs(x))) == 0","sympyTargetExpr":"log(x**2)","sympyTrapExpr":"2*log(x)","sympyValidExpr":"2*log(Abs(x))","verifiedStepLatex":"2\\ln|x|","whyTrapFailsExplanation":"At x = -3, ln((-3)²) = ln(9) is real, whereas 2·ln(-3) is undefined over the real numbers."},"coreRule":{"canonicalLatexFormula":"\\ln(x^2) = 2\\ln|x| \\quad (x \\neq 0)","conciseExplanation":"Real logarithms require strictly positive arguments (> 0). Thus ln(x²) expands to 2·ln|x| rather than 2·ln(x) when x can be negative.","estimatedSeconds":30,"ruleTitle":"Preserve Absolute Value When Dropping an Even Power","sympyCheckExpr":"log(x**2) == 2*log(Abs(x))"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x \\ge 4","optionId":"A","rationale":"Logarithms are also undefined when the argument equals zero."},{"isCorrect":true,"latexOrText":"x > 4","optionId":"B","rationale":"Spot on! Requiring x - 4 > 0 gives x > 4."},{"isCorrect":false,"latexOrText":"x \\neq 4","optionId":"C","rationale":"Values with x < 4 make the argument negative and are excluded too."}],"questionLatex":"\\ln(x - 4)","questionPrompt":"What is the real domain of ln(x - 4)?"}}'::jsonb, 'VERIFIED', 'b07aa1af7f2e739a15f57bc5a46b0d113270340a85aa24a6b4299880c6c25771', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000015', 'INEQ_NEGATIVE_MULT_NO_FLIP', 'tr-TR', '1.0.0', 'Negatif Sayıyla Çarpma/Bölmede Eşitsizlik Yönü', 'Odak Noktası · Eşitsizlikler', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x < -3","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies -2(0) = 0 < 6 \\text{ (True)}, \\; 0 < -3 \\text{ (False)}","promptLatex":"-2x < 6","sympyEquivalenceCheckExpr":"solveset(-2*x < 6, x, Reals) == Interval.open(-3, oo)","sympyTargetExpr":"-2*x < 6","sympyTrapExpr":"x < -3","sympyValidExpr":"x > -3","verifiedStepLatex":"x > -3","whyTrapFailsExplanation":"Yönü çevirmeden x < -3 yazıldığında x = 0 değeri -2(0) = 0 < 6 eşitsizliğini sağladığı hâlde küme dışında kalır."},"coreRule":{"canonicalLatexFormula":"-kx < b \\iff x > -\\frac{b}{k} \\quad (k > 0)","conciseExplanation":"Bir eşitsizliğin her iki tarafı negatif bir sayıyla çarpılır veya bölünürse sayı doğrusundaki sıralama tersine döndüğü için sembol yön değiştirir.","estimatedSeconds":30,"ruleTitle":"Negatif Sayıyla İşlem Yapınca Eşitsizlik Ters Döner","sympyCheckExpr":"-2*x < 6"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x \\ge -4","optionId":"A","rationale":"Negatif -3 ile bölünürken ≥ işareti ≤ işaretine dönmelidir."},{"isCorrect":true,"latexOrText":"x \\le -4","optionId":"B","rationale":"Harika! -3 ile bölerken yönü çevirerek doğru aralığı buldun."},{"isCorrect":false,"latexOrText":"x \\le 4","optionId":"C","rationale":"12 / (-3) işleminin işareti negatiftir: -4."}],"questionLatex":"-3x \\ge 12","questionPrompt":"-3x ≥ 12 eşitsizliğinin doğru çözümü hangisidir?"}}'::jsonb, 'VERIFIED', 'cbb5cde84f13cdde631d37090dff66472d20e958f66da50b988a04390867470f', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000016', 'INEQ_NEGATIVE_MULT_NO_FLIP', 'en-US', '1.0.0', 'Flipping the Inequality When Multiplying by a Negative', 'Focus Area · Inequalities', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x < -3","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies -2(0) = 0 < 6 \\text{ (True)}, \\; 0 < -3 \\text{ (False)}","promptLatex":"-2x < 6","sympyEquivalenceCheckExpr":"solveset(-2*x < 6, x, Reals) == Interval.open(-3, oo)","sympyTargetExpr":"-2*x < 6","sympyTrapExpr":"x < -3","sympyValidExpr":"x > -3","verifiedStepLatex":"x > -3","whyTrapFailsExplanation":"Keeping x < -3 excludes x = 0, even though -2(0) = 0 < 6 is true."},"coreRule":{"canonicalLatexFormula":"-kx < b \\iff x > -\\frac{b}{k} \\quad (k > 0)","conciseExplanation":"Multiplying or dividing both sides of an inequality by a negative number reverses order on the number line, so < becomes >.","estimatedSeconds":30,"ruleTitle":"Reverse the Inequality Sign on Negative Multiplication or Division","sympyCheckExpr":"-2*x < 6"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x \\ge -4","optionId":"A","rationale":"Dividing by -3 flips ≥ to ≤."},{"isCorrect":true,"latexOrText":"x \\le -4","optionId":"B","rationale":"Spot on! Dividing by -3 and flipping the sign gives x ≤ -4."},{"isCorrect":false,"latexOrText":"x \\le 4","optionId":"C","rationale":"Check the quotient sign: 12 / (-3) = -4."}],"questionLatex":"-3x \\ge 12","questionPrompt":"What is the solution to -3x ≥ 12?"}}'::jsonb, 'VERIFIED', '3ec7a1bca26309b8712978f6f2993d9690585865bb431b187e9bc3a1465db1d4', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000017', 'INEQ_CROSS_MULT_VARIABLE', 'tr-TR', '1.0.0', 'Eşitsizlikte Değişkenli Paydayla İçler Dışlar Yapmama', 'Odak Noktası · Rasyonel Eşitsizlik', 100, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x + 1 > 2x \\implies x < 1","counterexampleBindings":{"x":-1},"estimatedSeconds":35,"numericCounterexampleLatex":"x = -1 \\implies \\frac{-1 + 1}{-1} = 0 \\ngtr 2","promptLatex":"\\frac{x + 1}{x} > 2","sympyEquivalenceCheckExpr":"solveset((x + 1)/x > 2, x, Reals) == Interval.open(0, 1)","sympyTargetExpr":"(x + 1)/x > 2","sympyTrapExpr":"x < 1","sympyValidExpr":"And(x > 0, x < 1)","verifiedStepLatex":"\\frac{1 - x}{x} > 0 \\implies 0 < x < 1","whyTrapFailsExplanation":"Doğrudan x + 1 > 2x yazmak x = -1 değerini çözüm sanır; oysa (-1 + 1)/(-1) = 0 > 2 değildir."},"coreRule":{"canonicalLatexFormula":"\\frac{f(x)}{g(x)} > c \\iff \\frac{f(x) - c\\,g(x)}{g(x)} > 0","conciseExplanation":"Paydadaki x pozitif de negatif de olabilir; içler dışlar yapmak yerine terimleri bir tarafa toplayıp işaret tablosu kur.","estimatedSeconds":35,"ruleTitle":"İşareti Bilinmeyen Değişkenle Çarpmak Yerine Tek Tarafta Topla","sympyCheckExpr":"(x + 1)/x - 2 == (1 - x)/x"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x < 1","optionId":"A","rationale":"x < 0 iken paydayla çarpmak eşitsizliğin yönünü bozar; x = -1 sağlamaz."},{"isCorrect":true,"latexOrText":"0 < x < 1","optionId":"B","rationale":"Harika! (1 - x)/x > 0 için işaret tablosu 0 < x < 1 aralığını verir."},{"isCorrect":false,"latexOrText":"x > 1","optionId":"C","rationale":"x = 2 için (2 + 1)/2 = 1.5 > 2 sağlanmaz."}],"questionLatex":"\\frac{x + 1}{x} > 2","questionPrompt":"(x + 1)/x > 2 eşitsizliğini sağlayan x aralığı hangisidir?"}}'::jsonb, 'VERIFIED', '7ea92d9d9dfa616a9653ee997c240a13ae2105a12b7f294f868b47c92c622e6a', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000018', 'INEQ_CROSS_MULT_VARIABLE', 'en-US', '1.0.0', 'Avoiding Blind Cross-Multiplication in Inequalities', 'Focus Area · Rational Inequalities', 100, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x + 1 > 2x \\implies x < 1","counterexampleBindings":{"x":-1},"estimatedSeconds":35,"numericCounterexampleLatex":"x = -1 \\implies \\frac{-1 + 1}{-1} = 0 \\ngtr 2","promptLatex":"\\frac{x + 1}{x} > 2","sympyEquivalenceCheckExpr":"solveset((x + 1)/x > 2, x, Reals) == Interval.open(0, 1)","sympyTargetExpr":"(x + 1)/x > 2","sympyTrapExpr":"x < 1","sympyValidExpr":"And(x > 0, x < 1)","verifiedStepLatex":"\\frac{1 - x}{x} > 0 \\implies 0 < x < 1","whyTrapFailsExplanation":"Cross-multiplying into x + 1 > 2x accepts x = -1, yet (-1 + 1)/(-1) = 0 is not greater than 2."},"coreRule":{"canonicalLatexFormula":"\\frac{f(x)}{g(x)} > c \\iff \\frac{f(x) - c\\,g(x)}{g(x)} > 0","conciseExplanation":"Because a variable denominator can be positive or negative, subtract everything to one side and inspect signs instead of cross-multiplying.","estimatedSeconds":35,"ruleTitle":"Collect Terms on One Side and Build a Sign Chart","sympyCheckExpr":"(x + 1)/x - 2 == (1 - x)/x"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"x < 1","optionId":"A","rationale":"Negative values such as x = -1 do not satisfy the original inequality."},{"isCorrect":true,"latexOrText":"0 < x < 1","optionId":"B","rationale":"Spot on! Rewriting as (1 - x)/x > 0 isolates 0 < x < 1."},{"isCorrect":false,"latexOrText":"x > 1","optionId":"C","rationale":"At x = 2, (2 + 1)/2 = 1.5 is not greater than 2."}],"questionLatex":"\\frac{x + 1}{x} > 2","questionPrompt":"Which interval solves (x + 1)/x > 2?"}}'::jsonb, 'VERIFIED', '9f4aa3dccd333ff1bbd40029eab2e9889d7d1c2e30ddf59365ffd6d361cb9bd6', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000019', 'ABS_SINGLE_BRANCH_ONLY', 'tr-TR', '1.0.0', 'Mutlak Değer Denklemlerinde İki Dalı da Çözme', 'Odak Noktası · Mutlak Değer', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x - 2 = 5 \\implies \\{7\\}","counterexampleBindings":{"x":-3},"estimatedSeconds":30,"numericCounterexampleLatex":"x = -3 \\implies |-3 - 2| = |-5| = 5","promptLatex":"|x - 2| = 5","sympyEquivalenceCheckExpr":"Eq(Abs(x - 2), 5) <=> Or(Eq(x, 7), Eq(x, -3))","sympyTargetExpr":"Eq(Abs(x - 2), 5)","sympyTrapExpr":"Eq(x, 7)","sympyValidExpr":"Or(Eq(x, 7), Eq(x, -3))","verifiedStepLatex":"x - 2 = \\pm 5 \\implies \\{-3, 7\\}","whyTrapFailsExplanation":"Yalnızca x - 2 = 5 dalını çözmek x = -3 kökünü atlar; oysa |-3 - 2| = |-5| = 5 de geçerli bir çözümdür."},"coreRule":{"canonicalLatexFormula":"|u| = k \\; (k \\ge 0) \\iff u = k \\lor u = -k","conciseExplanation":"Sayı doğrusu üzerinde uzaklık iki yönde de ölçülebildiği için |x - 2| = 5 denklemi hem +5 hem -5 dallarıyla çözülmelidir.","estimatedSeconds":30,"ruleTitle":"|u| = k Denklemi Hem u = k Hem u = -k Verir","sympyCheckExpr":"Eq(Abs(x - 2), 5)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{7\\}","optionId":"A","rationale":"İkinci dal olan x - 4 = -3 denklemini de çözmelisin."},{"isCorrect":true,"latexOrText":"\\{1, 7\\}","optionId":"B","rationale":"Harika! x - 4 = 3 ve x - 4 = -3 dallarının ikisinden de 7 ve 1 bulundu."},{"isCorrect":false,"latexOrText":"\\{-1, 7\\}","optionId":"C","rationale":"x - 4 = -3 denkleminden x = 4 - 3 = +1 elde edilir."}],"questionLatex":"|x - 4| = 3","questionPrompt":"|x - 4| = 3 denkleminin çözüm kümesi nedir?"}}'::jsonb, 'VERIFIED', 'e1a5575c61282d1758fbbe8007cb9822fa42128d3f9c7ced5470c80de0822e78', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000020', 'ABS_SINGLE_BRANCH_ONLY', 'en-US', '1.0.0', 'Solving Both Branches of an Absolute Value Equation', 'Focus Area · Absolute Value', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"x - 2 = 5 \\implies \\{7\\}","counterexampleBindings":{"x":-3},"estimatedSeconds":30,"numericCounterexampleLatex":"x = -3 \\implies |-3 - 2| = |-5| = 5","promptLatex":"|x - 2| = 5","sympyEquivalenceCheckExpr":"Eq(Abs(x - 2), 5) <=> Or(Eq(x, 7), Eq(x, -3))","sympyTargetExpr":"Eq(Abs(x - 2), 5)","sympyTrapExpr":"Eq(x, 7)","sympyValidExpr":"Or(Eq(x, 7), Eq(x, -3))","verifiedStepLatex":"x - 2 = \\pm 5 \\implies \\{-3, 7\\}","whyTrapFailsExplanation":"Solving only x - 2 = 5 misses x = -3, even though |-3 - 2| = |-5| = 5."},"coreRule":{"canonicalLatexFormula":"|u| = k \\; (k \\ge 0) \\iff u = k \\lor u = -k","conciseExplanation":"Distance on the number line works in both directions, so |x - 2| = 5 requires solving both x - 2 = 5 and x - 2 = -5.","estimatedSeconds":30,"ruleTitle":"|u| = k Splits Into u = k and u = -k","sympyCheckExpr":"Eq(Abs(x - 2), 5)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"\\{7\\}","optionId":"A","rationale":"Include the negative branch x - 4 = -3 as well."},{"isCorrect":true,"latexOrText":"\\{1, 7\\}","optionId":"B","rationale":"Spot on! Solving x - 4 = 3 and x - 4 = -3 yields both 7 and 1."},{"isCorrect":false,"latexOrText":"\\{-1, 7\\}","optionId":"C","rationale":"From x - 4 = -3, adding 4 gives x = +1."}],"questionLatex":"|x - 4| = 3","questionPrompt":"What is the solution set of |x - 4| = 3?"}}'::jsonb, 'VERIFIED', '97a755453902fbe5640933f826129a90c9927cf3bacbfa9a0bc9058589b960c1', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000021', 'FUNC_COMPOSITION_ORDER', 'tr-TR', '1.0.0', 'Bileşke Fonksiyonda İçten Dışa Uygulama Sırası', 'Odak Noktası · Fonksiyon Bileşkesi', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"(2x + 1)^2","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies f(g(1)) = 2(1)^2 + 1 = 3 \\neq (2(1) + 1)^2 = 9","promptLatex":"f(x) = 2x + 1, \\; g(x) = x^2 \\implies (f \\circ g)(x)","sympyEquivalenceCheckExpr":"simplify((2*(x**2) + 1) - (2*x**2 + 1)) == 0","sympyTargetExpr":"2*(x**2) + 1","sympyTrapExpr":"(2*x + 1)**2","sympyValidExpr":"2*x**2 + 1","verifiedStepLatex":"2x^2 + 1","whyTrapFailsExplanation":"Sırayı ters alıp g(f(x)) hesaplamak (2x + 1)² verir; x = 1 için 3 yerine 9 üretir."},"coreRule":{"canonicalLatexFormula":"(f \\circ g)(x) = f(g(x)) \\neq g(f(x))","conciseExplanation":"Bileşke işleminde sağdaki fonksiyon girdiyi alır: (f ∘ g)(x) = f(g(x)). Fonksiyonların sırası genellikle değişmeli değildir.","estimatedSeconds":30,"ruleTitle":"(f ∘ g)(x) İfadesi Önce g(x), Sonra f İşlemini Uygular","sympyCheckExpr":"2*(x**2) + 1 == 2*x**2 + 1"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"16","optionId":"A","rationale":"16 değeri g(f(5)) = 2(5 + 3) sırasından gelir; önce g(5) hesaplanmalıdır."},{"isCorrect":true,"latexOrText":"13","optionId":"B","rationale":"Harika! Önce g(5) = 10, ardından f(10) = 10 + 3 = 13 bulundu."},{"isCorrect":false,"latexOrText":"11","optionId":"C","rationale":"f(g(5)) için g(5) = 10 sonucunu f(x) = x + 3 içine koymalısın."}],"questionLatex":"(f \\circ g)(5), \\; f(x)=x+3, \\; g(x)=2x","questionPrompt":"f(x) = x + 3 ve g(x) = 2x ise (f ∘ g)(5) kaçtır?"}}'::jsonb, 'VERIFIED', '423cd95420dd4731e94585b7f4ce290d6f5bb01091122b2470a7913213ba012c', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000022', 'FUNC_COMPOSITION_ORDER', 'en-US', '1.0.0', 'Evaluating Function Composition From Inside Out', 'Focus Area · Function Composition', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"(2x + 1)^2","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies f(g(1)) = 2(1)^2 + 1 = 3 \\neq (2(1) + 1)^2 = 9","promptLatex":"f(x) = 2x + 1, \\; g(x) = x^2 \\implies (f \\circ g)(x)","sympyEquivalenceCheckExpr":"simplify((2*(x**2) + 1) - (2*x**2 + 1)) == 0","sympyTargetExpr":"2*(x**2) + 1","sympyTrapExpr":"(2*x + 1)**2","sympyValidExpr":"2*x**2 + 1","verifiedStepLatex":"2x^2 + 1","whyTrapFailsExplanation":"Reversing to g(f(x)) produces (2x + 1)², which gives 9 instead of 3 at x = 1."},"coreRule":{"canonicalLatexFormula":"(f \\circ g)(x) = f(g(x)) \\neq g(f(x))","conciseExplanation":"Composition is not commutative: (f ∘ g)(x) = f(g(x)) feeds the output of the right-hand function g into f.","estimatedSeconds":30,"ruleTitle":"(f ∘ g)(x) Means Apply g First, Then f","sympyCheckExpr":"2*(x**2) + 1 == 2*x**2 + 1"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"16","optionId":"A","rationale":"16 comes from g(f(5)) = 2(5 + 3); evaluate the inner function g(5) first."},{"isCorrect":true,"latexOrText":"13","optionId":"B","rationale":"Spot on! g(5) = 10 first, then f(10) = 10 + 3 = 13."},{"isCorrect":false,"latexOrText":"11","optionId":"C","rationale":"Substitute g(5) = 10 into f(x) = x + 3."}],"questionLatex":"(f \\circ g)(5), \\; f(x)=x+3, \\; g(x)=2x","questionPrompt":"Given f(x) = x + 3 and g(x) = 2x, what is (f ∘ g)(5)?"}}'::jsonb, 'VERIFIED', '9af3708fcff3e01834b5a9dec8c3d9611f1149b2d8851df4615be0b3e1b415a6', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000023', 'TRIG_PERIOD_OMITTED', 'tr-TR', '1.0.0', 'Trigonometrik Denklemlerde Periyodun Ölçeklenmesi', 'Odak Noktası · Trigonometrik Periyot', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"\\sin\\left(2\\left(x + \\frac{\\pi}{2}\\right)\\right)","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies \\sin(2(1 + \\pi)) = \\sin(2) \\neq \\sin(2 + \\pi) = -\\sin(2)","promptLatex":"\\sin(2x)","sympyEquivalenceCheckExpr":"simplify(sin(2*(x + pi)) - sin(2*x)) == 0","sympyTargetExpr":"sin(2*x)","sympyTrapExpr":"sin(2*(x + pi/2))","sympyValidExpr":"sin(2*(x + pi))","verifiedStepLatex":"\\sin(2(x + \\pi))","whyTrapFailsExplanation":"2πk yerine π/2 kayması eklemek sin(2(x + π/2)) = -sin(2x) üretir; oysa sin(2x) fonksiyonunun temel periyodu π''dir."},"coreRule":{"canonicalLatexFormula":"\\sin(kx) \\text{ has period } \\frac{2\\pi}{|k|}","conciseExplanation":"sin(2x) = 1/2 denkleminde 2x = π/6 + 2πk yazıldıktan sonra iki taraf 2''ye bölünürse x = π/12 + πk olur; periyot π''ye iner.","estimatedSeconds":35,"ruleTitle":"Katsayıya Bölerken Periyot Terimini (+2πk) de Böl","sympyCheckExpr":"sin(2*(x + pi)) == sin(2*x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"2","optionId":"A","rationale":"Periyot π olduğu için [0, 2π) aralığında kök sayısı iki katına çıkar."},{"isCorrect":true,"latexOrText":"4","optionId":"B","rationale":"Harika! 2x = πk ⇒ x = πk/2 olduğundan {0, π/2, π, 3π/2} şeklinde 4 kök vardır."},{"isCorrect":false,"latexOrText":"1","optionId":"C","rationale":"sin(2x) = 0 denklemi her π/2 adımda bir sıfırlanır."}],"questionLatex":"\\sin(2x) = 0, \\quad x \\in [0, 2\\pi)","questionPrompt":"sin(2x) = 0 denkleminin [0, 2π) aralığında kaç farklı kökü vardır?"}}'::jsonb, 'VERIFIED', 'cdeb956f1fd709db355bfb1c931178accf416fcf7f7a48321e193c513e64898b', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000024', 'TRIG_PERIOD_OMITTED', 'en-US', '1.0.0', 'Scaling the Period Term in Trigonometric Equations', 'Focus Area · Trigonometric Period', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"\\sin\\left(2\\left(x + \\frac{\\pi}{2}\\right)\\right)","counterexampleBindings":{"x":1},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 1 \\implies \\sin(2(1 + \\pi)) = \\sin(2) \\neq \\sin(2 + \\pi) = -\\sin(2)","promptLatex":"\\sin(2x)","sympyEquivalenceCheckExpr":"simplify(sin(2*(x + pi)) - sin(2*x)) == 0","sympyTargetExpr":"sin(2*x)","sympyTrapExpr":"sin(2*(x + pi/2))","sympyValidExpr":"sin(2*(x + pi))","verifiedStepLatex":"\\sin(2(x + \\pi))","whyTrapFailsExplanation":"Shifting by π/2 flips the sign to -sin(2x), whereas the true fundamental period of sin(2x) is π."},"coreRule":{"canonicalLatexFormula":"\\sin(kx) \\text{ has period } \\frac{2\\pi}{|k|}","conciseExplanation":"When solving sin(2x) = c, writing 2x = α + 2πk and dividing by 2 scales the period to πk, not 2πk.","estimatedSeconds":35,"ruleTitle":"Divide +2πk by the Inner Frequency Coefficient","sympyCheckExpr":"sin(2*(x + pi)) == sin(2*x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"2","optionId":"A","rationale":"Because the period halves to π, twice as many solutions appear in [0, 2π)."},{"isCorrect":true,"latexOrText":"4","optionId":"B","rationale":"Spot on! 2x = πk gives x = πk/2, producing 4 solutions: 0, π/2, π, 3π/2."},{"isCorrect":false,"latexOrText":"1","optionId":"C","rationale":"Check x = π/2, π, and 3π/2 as well."}],"questionLatex":"\\sin(2x) = 0, \\quad x \\in [0, 2\\pi)","questionPrompt":"How many solutions does sin(2x) = 0 have on [0, 2π)?"}}'::jsonb, 'VERIFIED', 'c020c32ee3a2548480888b6063bb29fcfbb6bf4b5a63033fd0535e461f9d3ed1', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000025', 'CALC_LIMIT_INDETERMINATE_SUB', 'tr-TR', '1.0.0', '0/0 Belirsizliğinde Sadeleştirme Sonrası Limit', 'Odak Noktası · Limit Belirsizliği', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"0","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"x \\to 2 \\implies \\frac{(x-2)(x+2)}{x-2} = x + 2 \\to 4 \\neq 0","promptLatex":"\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2}","sympyEquivalenceCheckExpr":"Limit((x**2 - 4)/(x - 2), x, 2).doit() == 4","sympyTargetExpr":"Limit((x**2 - 4)/(x - 2), x, 2)","sympyTrapExpr":"0","sympyValidExpr":"4","verifiedStepLatex":"\\lim_{x \\to 2}(x + 2) = 4","whyTrapFailsExplanation":"0/0 belirsizliğini 0 veya tanımsız kabul etmek gerçek limit değerini kaçırır; (x - 2)(x + 2)/(x - 2) = x + 2 → 4 olur."},"coreRule":{"canonicalLatexFormula":"\\lim_{x \\to a} \\frac{x^2 - a^2}{x - a} = \\lim_{x \\to a}(x + a) = 2a","conciseExplanation":"Doğrudan yerine koyma 0/0 veriyorsa pay ve paydada sıfır yapan (x - a) çarpanını sadeleştirip ardından limiti hesapla.","estimatedSeconds":30,"ruleTitle":"0/0 Sonucu Cevap Değildir; Çarpanlara Ayırıp Sadeleştir","sympyCheckExpr":"Limit((x**2 - 4)/(x - 2), x, 2) == 4"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"0","optionId":"A","rationale":"0/0 bir belirsizlik biçimidir; önce (x - 3) çarpanları sadeleştirilmelidir."},{"isCorrect":true,"latexOrText":"6","optionId":"B","rationale":"Harika! (x - 3)(x + 3)/(x - 3) = x + 3 olduğundan x → 3 için 3 + 3 = 6 bulunur."},{"isCorrect":false,"latexOrText":"3","optionId":"C","rationale":"Sadeleştirme sonrası kalan ifade x + 3 olur: 3 + 3 = 6."}],"questionLatex":"\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}","questionPrompt":"lim_{x → 3} (x^2 - 9)/(x - 3) limitinin değeri kaçtır?"}}'::jsonb, 'VERIFIED', '33ec0d7dc94a9407b20c56a370359a172070f119e8928f8c354f7226ee0da97f', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000026', 'CALC_LIMIT_INDETERMINATE_SUB', 'en-US', '1.0.0', 'Resolving 0/0 Indeterminate Limits by Factoring', 'Focus Area · Limits', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"0","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"x \\to 2 \\implies \\frac{(x-2)(x+2)}{x-2} = x + 2 \\to 4 \\neq 0","promptLatex":"\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2}","sympyEquivalenceCheckExpr":"Limit((x**2 - 4)/(x - 2), x, 2).doit() == 4","sympyTargetExpr":"Limit((x**2 - 4)/(x - 2), x, 2)","sympyTrapExpr":"0","sympyValidExpr":"4","verifiedStepLatex":"\\lim_{x \\to 2}(x + 2) = 4","whyTrapFailsExplanation":"Treating 0/0 as 0 overlooks that (x - 2)(x + 2)/(x - 2) equals x + 2 near 2, approaching 4."},"coreRule":{"canonicalLatexFormula":"\\lim_{x \\to a} \\frac{x^2 - a^2}{x - a} = \\lim_{x \\to a}(x + a) = 2a","conciseExplanation":"When direct substitution produces 0/0, factor and cancel the common (x - a) factor before evaluating the limit.","estimatedSeconds":30,"ruleTitle":"0/0 Signals Algebraic Cancellation, Not Zero","sympyCheckExpr":"Limit((x**2 - 4)/(x - 2), x, 2) == 4"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"0","optionId":"A","rationale":"0/0 is indeterminate; cancel the common (x - 3) factor first."},{"isCorrect":true,"latexOrText":"6","optionId":"B","rationale":"Spot on! Canceling (x - 3) leaves x + 3, which approaches 3 + 3 = 6."},{"isCorrect":false,"latexOrText":"3","optionId":"C","rationale":"After canceling (x - 3), substitute 3 into x + 3."}],"questionLatex":"\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}","questionPrompt":"What is lim_{x → 3} (x^2 - 9)/(x - 3)?"}}'::jsonb, 'VERIFIED', '60d76d0a81aa78788b12af1c00f958db63080276685471f91cd98562bf05ab99', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000027', 'CALC_CHAIN_RULE_OMITTED', 'tr-TR', '1.0.0', 'Bileşke Türevde İç Fonksiyon Türevi (Zincir Kuralı)', 'Odak Noktası · Zincir Kuralı', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"4(3x + 1)^3","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies 12(1)^3 = 12 \\neq 4(1)^3 = 4","promptLatex":"\\frac{d}{dx}\\left[(3x + 1)^4\\right]","sympyEquivalenceCheckExpr":"simplify(diff((3*x + 1)**4, x) - 12*(3*x + 1)**3) == 0","sympyTargetExpr":"diff((3*x + 1)**4, x)","sympyTrapExpr":"4*(3*x + 1)**3","sympyValidExpr":"12*(3*x + 1)**3","verifiedStepLatex":"12(3x + 1)^3","whyTrapFailsExplanation":"İç türev olan 3 çarpanını unutmak 4(3x + 1)³ verir; x = 0 noktasında gerçek eğim 12 yerine 4 çıkar."},"coreRule":{"canonicalLatexFormula":"\\frac{d}{dx}[f(g(x))] = f''(g(x)) \\cdot g''(x)","conciseExplanation":"f(g(x)) türevlenirken yalnızca dış üs kuralı yetmez; sonuç mutlaka g''(x) iç türevi ile çarpılmalıdır.","estimatedSeconds":30,"ruleTitle":"Dış Türevin Ardından İç Fonksiyonun Türeviyle Çarp","sympyCheckExpr":"diff((3*x + 1)**4, x) == 12*(3*x + 1)**3"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"3(2x - 5)^2","optionId":"A","rationale":"İçteki (2x - 5) ifadesinin türevi olan 2 ile çarpmayı unutmayalım."},{"isCorrect":true,"latexOrText":"6(2x - 5)^2","optionId":"B","rationale":"Harika! Dış türev 3(2x - 5)² ile iç türev 2 çarpılarak 6(2x - 5)² elde edildi."},{"isCorrect":false,"latexOrText":"6(2x - 5)^3","optionId":"C","rationale":"Üs bir azalarak 3 - 1 = 2 olmalıdır."}],"questionLatex":"\\frac{d}{dx}\\left[(2x - 5)^3\\right]","questionPrompt":"d/dx [(2x - 5)^3] türevi aşağıdakilerden hangisidir?"}}'::jsonb, 'VERIFIED', '2232ebf70cac468980d6301e3b02b2d60b9cdada68d9bd7a645affb755f48023', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000028', 'CALC_CHAIN_RULE_OMITTED', 'en-US', '1.0.0', 'Remembering the Inner Derivative in the Chain Rule', 'Focus Area · Chain Rule', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"4(3x + 1)^3","counterexampleBindings":{"x":0},"estimatedSeconds":30,"numericCounterexampleLatex":"x = 0 \\implies 12(1)^3 = 12 \\neq 4(1)^3 = 4","promptLatex":"\\frac{d}{dx}\\left[(3x + 1)^4\\right]","sympyEquivalenceCheckExpr":"simplify(diff((3*x + 1)**4, x) - 12*(3*x + 1)**3) == 0","sympyTargetExpr":"diff((3*x + 1)**4, x)","sympyTrapExpr":"4*(3*x + 1)**3","sympyValidExpr":"12*(3*x + 1)**3","verifiedStepLatex":"12(3x + 1)^3","whyTrapFailsExplanation":"Omitting the inner derivative factor of 3 yields 4(3x + 1)³, giving slope 4 instead of 12 at x = 0."},"coreRule":{"canonicalLatexFormula":"\\frac{d}{dx}[f(g(x))] = f''(g(x)) \\cdot g''(x)","conciseExplanation":"When differentiating a composite function f(g(x)), always multiply the outer derivative f''(g(x)) by the inner derivative g''(x).","estimatedSeconds":30,"ruleTitle":"Multiply Outer Derivative by Inner Derivative g''(x)","sympyCheckExpr":"diff((3*x + 1)**4, x) == 12*(3*x + 1)**3"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"3(2x - 5)^2","optionId":"A","rationale":"Remember to multiply by the inner derivative d/dx(2x - 5) = 2."},{"isCorrect":true,"latexOrText":"6(2x - 5)^2","optionId":"B","rationale":"Spot on! 3(2x - 5)² · 2 = 6(2x - 5)²."},{"isCorrect":false,"latexOrText":"6(2x - 5)^3","optionId":"C","rationale":"The outer power decreases from 3 to 2."}],"questionLatex":"\\frac{d}{dx}\\left[(2x - 5)^3\\right]","questionPrompt":"What is d/dx [(2x - 5)^3]?"}}'::jsonb, 'VERIFIED', 'c8db219b6e78fb83b2ff3e70b0477f7d6d9bf741295e6da48d4b19f4c830b8ae', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000029', 'CALC_PRODUCT_QUOTIENT_NAIVE', 'tr-TR', '1.0.0', 'Çarpımın Türevi (f''g + fg'') Kuralı', 'Odak Noktası · Çarpım Türevi', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"2x \\cos(x)","counterexampleBindings":{"x":1},"estimatedSeconds":35,"numericCounterexampleLatex":"x = 1 \\implies 2\\sin(1) + \\cos(1) \\neq 2\\cos(1)","promptLatex":"\\frac{d}{dx}\\left[x^2 \\sin(x)\\right]","sympyEquivalenceCheckExpr":"simplify(diff(x**2 * sin(x), x) - (2*x*sin(x) + x**2*cos(x))) == 0","sympyTargetExpr":"diff(x**2 * sin(x), x)","sympyTrapExpr":"2*x*cos(x)","sympyValidExpr":"2*x*sin(x) + x**2*cos(x)","verifiedStepLatex":"2x\\sin(x) + x^2\\cos(x)","whyTrapFailsExplanation":"2x ile cos(x)''i doğrudan çarpmak f''g + fg'' toplamındaki iki terimi bozar; x = 1 için 2sin(1)+cos(1) yerine 2cos(1) üretir."},"coreRule":{"canonicalLatexFormula":"(f \\cdot g)'' = f''g + fg''","conciseExplanation":"(f·g)'' ifadesi f''·g'' değil, sırayla birinin türevini alıp diğerini sabit tutarak toplanan f''g + fg'' biçimindedir.","estimatedSeconds":30,"ruleTitle":"Çarpımın Türevi Türevlerin Çarpımı Değildir","sympyCheckExpr":"diff(x**2 * sin(x), x) == 2*x*sin(x) + x**2*cos(x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"e^x","optionId":"A","rationale":"Çarpım türevi (1)·e^x + x·e^x toplamını gerektirir."},{"isCorrect":true,"latexOrText":"(x + 1)e^x","optionId":"B","rationale":"Harika! (x)''e^x + x(e^x)'' = e^x + x·e^x = (x + 1)e^x."},{"isCorrect":false,"latexOrText":"x e^x","optionId":"C","rationale":"İlk terim olan (x)''·e^x = e^x eklenmelidir."}],"questionLatex":"\\frac{d}{dx}\\left[x \\cdot e^x\\right]","questionPrompt":"d/dx [x · e^x] türevi hangisidir?"}}'::jsonb, 'VERIFIED', 'deddc1d64dc56a22693b3d5c2e3da5f1dc9ffe7022770e58e7adee7a9b7f6781', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000030', 'CALC_PRODUCT_QUOTIENT_NAIVE', 'en-US', '1.0.0', 'Applying the Product Rule Instead of Multiplying Derivatives', 'Focus Area · Product Rule', 95, '{"brokenVsValidCounterexample":{"commonTrapLatex":"2x \\cos(x)","counterexampleBindings":{"x":1},"estimatedSeconds":35,"numericCounterexampleLatex":"x = 1 \\implies 2\\sin(1) + \\cos(1) \\neq 2\\cos(1)","promptLatex":"\\frac{d}{dx}\\left[x^2 \\sin(x)\\right]","sympyEquivalenceCheckExpr":"simplify(diff(x**2 * sin(x), x) - (2*x*sin(x) + x**2*cos(x))) == 0","sympyTargetExpr":"diff(x**2 * sin(x), x)","sympyTrapExpr":"2*x*cos(x)","sympyValidExpr":"2*x*sin(x) + x**2*cos(x)","verifiedStepLatex":"2x\\sin(x) + x^2\\cos(x)","whyTrapFailsExplanation":"Multiplying 2x by cos(x) skips the sum structure and evaluates to 2cos(1) instead of 2sin(1) + cos(1) at x = 1."},"coreRule":{"canonicalLatexFormula":"(f \\cdot g)'' = f''g + fg''","conciseExplanation":"Differentiating a product requires two terms: the first derivative times the second, plus the first times the second derivative.","estimatedSeconds":30,"ruleTitle":"(fg)'' Equals f''g + fg'', Never f''g''","sympyCheckExpr":"diff(x**2 * sin(x), x) == 2*x*sin(x) + x**2*cos(x)"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"e^x","optionId":"A","rationale":"Multiplying derivatives gives 1·e^x, missing the + x·e^x term."},{"isCorrect":true,"latexOrText":"(x + 1)e^x","optionId":"B","rationale":"Spot on! (1)e^x + x(e^x) = (x + 1)e^x."},{"isCorrect":false,"latexOrText":"x e^x","optionId":"C","rationale":"Include the first product-rule term (1)·e^x."}],"questionLatex":"\\frac{d}{dx}\\left[x \\cdot e^x\\right]","questionPrompt":"What is d/dx [x · e^x]?"}}'::jsonb, 'VERIFIED', '24d9d1217cae49f232b7d3a6da678737e13333470c63d581492afc1e94f299cb', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000031', 'CALC_INTEGRAL_BOUNDS_SWAPPED', 'tr-TR', '1.0.0', 'Belirli İntegralde Sınırların Yer Değiştirmesi', 'Odak Noktası · İntegral Sınırları', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"8","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"\\left[x^2\\right]_{3}^{1} = 1^2 - 3^2 = -8 \\neq 8","promptLatex":"\\int_{3}^{1} 2x\\,dx","sympyEquivalenceCheckExpr":"integrate(2*x, (x, 3, 1)) == -8","sympyTargetExpr":"integrate(2*x, (x, 3, 1))","sympyTrapExpr":"8","sympyValidExpr":"-8","verifiedStepLatex":"-8","whyTrapFailsExplanation":"İşareti ters çevirmeyi unutmak +8 verir; oysa [x²]_3^1 = 1² - 3² = -8 olmalıdır."},"coreRule":{"canonicalLatexFormula":"\\int_{b}^{a} f(x)\\,dx = -\\int_{a}^{b} f(x)\\,dx","conciseExplanation":"∫_a^b f(x)dx = F(b) - F(a) olduğundan sınırlar ters çevrildiğinde F(a) - F(b) = -∫_a^b f(x)dx elde edilir.","estimatedSeconds":30,"ruleTitle":"Alt ve Üst Sınır Yer Değiştirirse İşaret Ters Döner","sympyCheckExpr":"integrate(2*x, (x, 3, 1)) == -integrate(2*x, (x, 1, 3))"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"15","optionId":"A","rationale":"Alt sınır 4 üst sınırdan büyük olduğu için sonuç negatif (-15) olmalıdır."},{"isCorrect":true,"latexOrText":"-15","optionId":"B","rationale":"Harika! [x²]_4^1 = 1² - 4² = 1 - 16 = -15."},{"isCorrect":false,"latexOrText":"-17","optionId":"C","rationale":"1² - 4² = 1 - 16 = -15 değerini kontrol edelim."}],"questionLatex":"\\int_{4}^{1} 2x\\,dx","questionPrompt":"∫_4^1 2x dx belirli integralinin değeri kaçtır?"}}'::jsonb, 'VERIFIED', '09f792c30b2208fb22566a298a1493714245b91da22712179a1cb04c0b6bee07', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000032', 'CALC_INTEGRAL_BOUNDS_SWAPPED', 'en-US', '1.0.0', 'Sign Flip When Definite Integral Limits Swap', 'Focus Area · Integral Bounds', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"8","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"\\left[x^2\\right]_{3}^{1} = 1^2 - 3^2 = -8 \\neq 8","promptLatex":"\\int_{3}^{1} 2x\\,dx","sympyEquivalenceCheckExpr":"integrate(2*x, (x, 3, 1)) == -8","sympyTargetExpr":"integrate(2*x, (x, 3, 1))","sympyTrapExpr":"8","sympyValidExpr":"-8","verifiedStepLatex":"-8","whyTrapFailsExplanation":"Ignoring the reversed limits gives +8, whereas [x²]_3^1 = 1² - 3² = -8."},"coreRule":{"canonicalLatexFormula":"\\int_{b}^{a} f(x)\\,dx = -\\int_{a}^{b} f(x)\\,dx","conciseExplanation":"By F(upper) - F(lower), reversing the limits negates the value: ∫_b^a f(x)dx = -∫_a^b f(x)dx.","estimatedSeconds":30,"ruleTitle":"Swapping Lower and Upper Bounds Negates the Integral","sympyCheckExpr":"integrate(2*x, (x, 3, 1)) == -integrate(2*x, (x, 1, 3))"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"15","optionId":"A","rationale":"Because the lower limit exceeds the upper limit, the integral is negated."},{"isCorrect":true,"latexOrText":"-15","optionId":"B","rationale":"Spot on! [x²]_4^1 = 1² - 4² = -15."},{"isCorrect":false,"latexOrText":"-17","optionId":"C","rationale":"Check the arithmetic: 1 - 16 = -15."}],"questionLatex":"\\int_{4}^{1} 2x\\,dx","questionPrompt":"What is the value of ∫_4^1 2x dx?"}}'::jsonb, 'VERIFIED', 'e28a3330199dc820705b1da0435db4348ecf461bc40df42ed1f653843ca7e602', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000033', 'WORD_VARIABLE_MISASSIGNMENT', 'tr-TR', '1.0.0', 'Problem Cümlesini Doğru Değişkene Bağlama', 'Odak Noktası · Denklem Kurma', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"3y = 48 \\implies y = 16","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"y = 16 \\implies 3(16) + 16 = 64 \\neq 48; \\; y = 12 \\implies 36 + 12 = 48","promptLatex":"A = 3y, \\; A + y = 48 \\implies y = ?","sympyEquivalenceCheckExpr":"48/(1 + 3) == 12","sympyTargetExpr":"48 / (1 + 3)","sympyTrapExpr":"16","sympyValidExpr":"12","verifiedStepLatex":"3y + y = 48 \\implies y = 12","whyTrapFailsExplanation":"Ayşe''nin payı y''yi toplam denklemden düşüp doğrudan 3y = 48 kurmak y = 16 verir; oysa 3(16) + 16 = 64 ≠ 48 olur."},"coreRule":{"canonicalLatexFormula":"A = k\\,y \\land A + y = T \\implies (k + 1)y = T","conciseExplanation":"''Ali''nin kitapları Ayşe''nin 3 katıdır ve toplam 48 kitap vardır'' cümlesinde A = 3y ve A + y = 48 olur; toplamda 4y = 48 kurulur.","estimatedSeconds":30,"ruleTitle":"Toplam İlişkisini Kurarken Tüm Terimleri Aynı Değişkenle Yaz","sympyCheckExpr":"48/(1 + 3) == 12"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"15","optionId":"A","rationale":"60/4 = 15 işleminde mavilerin kendi payı (+m) denkleme eklenmemiş olur."},{"isCorrect":true,"latexOrText":"12","optionId":"B","rationale":"Harika! 4m + m = 5m = 60 ⇒ m = 12 (kırmızı 48, toplam 60)."},{"isCorrect":false,"latexOrText":"48","optionId":"C","rationale":"48 kırmızı bilye sayısıdır; soru mavi bilye sayısını (m) sormaktadır."}],"questionLatex":"K = 4m, \\; K + m = 60","questionPrompt":"Bir kutuda kırmızı bilye sayısı mavinin 4 katıdır. Toplam 60 bilye varsa kaç mavi bilye vardır?"}}'::jsonb, 'VERIFIED', 'bc6843726440d7230a201e5c3f40d156673b714e15cb7006d2e4e70ff5f6a270', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
INSERT INTO micro_lesson_catalog (card_id, mistake_code, locale, schema_version, title, focus_badge_label, estimated_duration_seconds, card_payload, verification_status, verification_hash, verifier_version) VALUES ('00000000-0000-4000-8601-000000000034', 'WORD_VARIABLE_MISASSIGNMENT', 'en-US', '1.0.0', 'Mapping Every Quantity in Word-Problem Equations', 'Focus Area · Equation Modeling', 90, '{"brokenVsValidCounterexample":{"commonTrapLatex":"3y = 48 \\implies y = 16","counterexampleBindings":{},"estimatedSeconds":30,"numericCounterexampleLatex":"y = 16 \\implies 3(16) + 16 = 64 \\neq 48; \\; y = 12 \\implies 36 + 12 = 48","promptLatex":"A = 3y, \\; A + y = 48 \\implies y = ?","sympyEquivalenceCheckExpr":"48/(1 + 3) == 12","sympyTargetExpr":"48 / (1 + 3)","sympyTrapExpr":"16","sympyValidExpr":"12","verifiedStepLatex":"3y + y = 48 \\implies y = 12","whyTrapFailsExplanation":"Omitting + y and solving 3y = 48 gives y = 16, which produces 3(16) + 16 = 64 instead of 48."},"coreRule":{"canonicalLatexFormula":"A = k\\,y \\land A + y = T \\implies (k + 1)y = T","conciseExplanation":"When one quantity is 3 times another (A = 3y) and their total is 48, substitute into A + y = 48 to get 4y = 48.","estimatedSeconds":30,"ruleTitle":"Include Both Parts in the Total Equation","sympyCheckExpr":"48/(1 + 3) == 12"},"interactiveQuickCheck":{"correctOptionId":"B","estimatedSeconds":30,"options":[{"isCorrect":false,"latexOrText":"15","optionId":"A","rationale":"60/4 = 15 drops the +b term from R + b = 60."},{"isCorrect":true,"latexOrText":"12","optionId":"B","rationale":"Spot on! 4b + b = 5b = 60 gives b = 12 blue marbles (and 48 red)."},{"isCorrect":false,"latexOrText":"48","optionId":"C","rationale":"48 is the red count; the question asks for blue marbles b."}],"questionLatex":"R = 4b, \\; R + b = 60","questionPrompt":"Red marbles are 4 times blue marbles, and there are 60 in total. How many blue marbles are there?"}}'::jsonb, 'VERIFIED', '8f4f43a371ea1d3fa94a59d966965ada8253fd375bcf773f2ffa899a4ccce31d', 'sympy-1.12-v1') ON CONFLICT (mistake_code, locale) DO NOTHING;
